<?php $types=['question'=>'문의','error'=>'오류','feature'=>'기능'];$priorities=['normal'=>'일반','high'=>'높음','urgent'=>'긴급'];$statuses=['open'=>'접수','in_progress'=>'처리 중','answered'=>'답변 완료','closed'=>'종료']; foreach($tickets as $ticket): ?><section class="panel"><div class="section-head"><div><h2>#<?= (int)$ticket['id'] ?> <?= View::e($ticket['subject']) ?></h2><p><?= View::e($ticket['church_name']) ?> · <?= View::e($types[$ticket['ticket_type']]??$ticket['ticket_type']) ?> · <?= View::e($priorities[$ticket['priority']]??$ticket['priority']) ?> · <?= View::e($statuses[$ticket['status']]??$ticket['status']) ?></p></div><small><?= View::e($ticket['created_at']) ?></small></div><p><?= nl2br(View::e($ticket['body'])) ?></p><?php if($ticket['related_url']): ?><p><a href="<?= View::e($ticket['related_url']) ?>" target="_blank" rel="noopener noreferrer">관련 화면 열기</a></p><?php endif; ?><form method="post" action="/control/support/<?= (int)$ticket['id'] ?>/review" class="form-grid"><input type="hidden" name="_token" value="<?= View::e(Csrf::token()) ?>"><label>처리 상태<select name="status" required><?php foreach(['in_progress'=>'처리 중','answered'=>'답변 완료','closed'=>'종료'] as $value=>$label): ?><option value="<?= $value ?>" <?= $ticket['status']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="full">답변·처리 메모<textarea name="response_summary" maxlength="10000" rows="4"><?= View::e($ticket['response_summary']??'') ?></textarea></label><button class="button primary" type="submit">처리 내용 저장</button></form></section><?php endforeach; ?><?php if($tickets===[]): ?><section class="panel empty">조건에 맞는 문의가 없습니다.</section><?php endif; ?>
